package com.photopilot.ui.gui;

import java.util.List;
import java.util.Objects;
import java.util.stream.IntStream;
import javafx.scene.Node;
import javafx.scene.control.Dialog;
import javafx.scene.image.*;
import javafx.scene.layout.StackPane;
import javafx.scene.shape.*;
import javafx.stage.*;

/**
 * One outline icon family for the whole application, so it scales cleanly. The PhotoPilot logo is the one
 * raster asset: classpath PNGs generated by tools/GenerateAppIcons.java.
 */
final class AppIcons {
    static final String PLUS = "M12 2.5a9.5 9.5 0 1 0 0 19a9.5 9.5 0 1 0 0-19 M12 7.5v9 M7.5 12h9";
    static final String PENCIL = "M16.5 3.5l4 4L8 20l-5 1 1-5L16.5 3.5z M14 6l4 4";
    static final String TRASH = "M3.5 6h17 M9 6V3h6v3 M5.5 6l1.2 15h10.6l1.2-15 M10 10.5v6.5 M14 10.5v6.5";
    static final String PERSON = "M12 3a4.8 4.8 0 1 0 0 9.6a4.8 4.8 0 1 0 0-9.6 M3.8 21c.4-4.6 3.8-6.6 8.2-6.6s7.800 2 8.200 6.600z";
    static final String ARROW = "M0 12h25 M16 3.500l9 8.500-9 8.500";
    static final String PREVIOUS = "M15 4l-8 8 8 8";
    static final String NEXT = "M9 4l8 8-8 8";
    static final String MINIMIZE = "M0 6h13";
    static final String MAXIMIZE = "M2.500 0h8q2.500 0 2.500 2.500v8q0 2.500-2.500 2.500h-8q-2.500 0-2.500-2.500v-8q0-2.500 2.500-2.500z";
    static final String CLOSE = "M.5 .5l12 12 M12.500 .5l-12 12";
    static final String HOUSE = "M3.500 11.500L12 4l8.500 7.500 M6 9.500V20h12V9.500 M10 20v-6h4v6";
    static final String HISTORY = "M12 3.500a8.500 8.500 0 1 0 0 17a8.500 8.500 0 1 0 0-17 M12 7.500V12l3 2";
    static final String BULB = "M9.500 18h5 M10.500 21h3 M12 3a6.500 6.500 0 0 0-4 11.600c.7.6 1 1.300 1 2.400h6c0-1.100.3-1.800 1-2.400A6.500 6.500 0 0 0 12 3z";
    static final String DOCUMENT = "M6 3h9l4 4v14H6z M14.500 3v4.500H19 M9 12h7 M9 16h7";
    static final String CALENDAR = "M4 6h16v15H4z M4 10.500h16 M8.500 3.500v5 M15.500 3.500v5";
    static final String CAMERA_OUTLINE = "M3.500 8h4.200l1.600-2.500h5.400L16.300 8h4.200v11.500h-17z M12 10a3.500 3.500 0 1 0 0 7a3.500 3.500 0 1 0 0-7";
    static final String GRID = "M4 4h7v7H4z M13 4h7v7h-7z M4 13h7v7H4z M13 13h7v7h-7z";
    static final String CHART = "M4 20h16 M7 20v-7 M12 20V6 M17 20v-10";
    static final String LINK = "M10 14a4 4 0 0 0 6 .4l3-3a4 4 0 0 0-5.700-5.700l-1.300 1.300 M14 10a4 4 0 0 0-6-.4l-3 3a4 4 0 0 0 5.700 5.700l1.300-1.300";
    static final String CALCULATOR = "M6 3h12v18H6z M9 6.500h6v3H9z M9 13h.8 M11.600 13h.8 M14.200 13h.8 M9 17h.8 M11.600 17h.8 M14.200 17h.8";
    static final String CLOUD = "M7 18.500a4 4 0 0 1-.6-8a5.500 5.500 0 0 1 10.600-1a4.500 4.500 0 0 1 .5 9z";
    static final String INSPECT = "M10.500 3.500a7 7 0 1 0 0 14a7 7 0 1 0 0-14 M15.700 15.700L21 21 M8 13v-2.500 M10.500 13V8 M13 13V9.500";
    static final String GEAR = "M12 8.500a3.500 3.500 0 1 0 0 7a3.500 3.500 0 1 0 0-7 M12 2.500v3 M12 18.500v3 M2.500 12h3 M18.500 12h3 M5.300 5.300l2.100 2.100 M16.600 16.600l2.100 2.100 M5.300 18.700l2.100-2.100 M16.600 7.400l2.100-2.100";
    static final String CHEVRON_DOWN = "M2 4l5 5 5-5";
    private static final int[] LOGO_SIZES = { 16, 32, 48, 64, 128, 256, 512 };

    private AppIcons() { }
    /** Decoded once on first use; Image is immutable, so every window shares the same instances. */
    private static final class Logo {
        static final List<Image> IMAGES = IntStream.of(LOGO_SIZES).mapToObj(size -> new Image(Objects.requireNonNull(
            AppIcons.class.getResource("icons/photopilot-" + size + ".png"), "Missing logo resource " + size).toExternalForm())).toList();
    }
    static List<Image> logoImages() { return Logo.IMAGES; }
    /** Window, taskbar and Alt+Tab icon; the platform picks the closest size. */
    static void windowIcon(Stage stage) { stage.getIcons().setAll(Logo.IMAGES); }
    static void windowIcon(Dialog<?> dialog) { windowIcon((Stage) dialog.getDialogPane().getScene().getWindow()); }
    /** The PhotoPilot logo as a size x size node, from the smallest PNG that covers the primary screen's scale. */
    static Node logo(double size) {
        double pixels = size * Screen.getPrimary().getOutputScaleX();
        var image = Logo.IMAGES.stream().filter(candidate -> candidate.getWidth() >= pixels).findFirst().orElse(Logo.IMAGES.getLast());
        var view = new ImageView(image); view.setFitWidth(size); view.setFitHeight(size); view.setPreserveRatio(true); view.setSmooth(true);
        return view;
    }
    /** Fixed-size box, so labels beside icons of different shapes stay aligned. */
    static StackPane slot(String content, String style, double size) {
        var slot = new StackPane(outline(content, style)); slot.setMinSize(size, size); slot.setPrefSize(size, size); slot.setMaxSize(size, size); return slot;
    }
    static String feature(String id) {
        return switch (id) {
            case "F01" -> HISTORY; case "F02" -> BULB; case "F03" -> DOCUMENT; case "F04" -> CAMERA_OUTLINE; case "F05" -> GRID; case "F06" -> CHART;
            case "F07" -> LINK; case "F08" -> CALCULATOR; case "F09" -> CLOUD; case "F10" -> CALENDAR; default -> INSPECT;
        };
    }
    static SVGPath outline(String content, String style) {
        var path = new SVGPath(); path.setContent(content); path.getStyleClass().add(style); return path;
    }
}
